// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedAmount) internal {
        bool reverted;
        try c.seedMarket(seedAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted ? (c.initialized() == false) : (c.initialized() == true && c.marketDrugs() == seedAmount));
    }

    function testFuzz_run(uint256 seedAmount) public {
        _run(seedAmount);
    }

    receive() external payable {}
}
